    },
    {
      "name": "Polynomial.coeff_update_same",
      "type": " {R : Type u} [Semiring R] (p : Polynomial R) (n : ℕ) (a : R) : (p.update n a).coeff n = a",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.coeff_X_zero",
      "type": " {R : Type u} [Semiring R] : Polynomial.X.coeff 0 = 0",
