    },
    {
      "name": "Polynomial.erase_same",
      "type": " {R : Type u} [Semiring R] (p : Polynomial R) (n : ℕ) : (Polynomial.erase n p).coeff n = 0",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    }
  ]
